import random
import time
from functools import wraps


def retry(max_attempts=5, base_delay=0.5, max_delay=30.0, factor=2.0,
          jitter=True, exceptions=(Exception,)):
    """Retry the decorated function with exponential backoff.

    Delay before retry n (1-based) is min(max_delay, base_delay * factor**(n-1)),
    randomised to [0, delay] when jitter is on. The last exception is re-raised
    once max_attempts calls have failed.
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == max_attempts:
                        raise
                    delay = min(max_delay, base_delay * factor ** (attempt - 1))
                    if jitter:
                        delay = random.uniform(0, delay)
                    time.sleep(delay)
        return wrapper
    return decorator
